import sys
from collections import defaultdict, deque

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

def main():
    N = int(sys.stdin.readline().strip())
    graph = defaultdict(list)
    for _ in range(N - 1):
        U, V = read_ints()
        graph[U].append(V)
        graph[V].append(U)

    def bfs(start):
        visited = [False] * N
        queue = deque([start])
        visited[start] = True
        potential = 0
        while queue:
            node = queue.popleft()
            potential += 1
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return potential

    max_potential = 0
    for i in range(N):
        max_potential += bfs(i)

    print(max_potential)

